mapper.select:
SELECT
       (
           SELECT COUNT(*)
           FROM TB_COMM_POST P
           WHERE P.USR_ID = #{usrId}
             AND P.POST_STAT = 'ACTIVE'
       ) AS postCount
    ,  (
           SELECT COUNT(*)
           FROM TB_COMM_FOLLOW F
           WHERE F.FOLLOWING_USR_ID = #{usrId}
             AND F.FOLLOW_STAT = 'ACCEPTED'
       ) AS followerCount
    ,  (
           SELECT COUNT(*)
           FROM TB_COMM_FOLLOW F
           WHERE F.FOLLOWER_USR_ID = #{usrId}
             AND F.FOLLOW_STAT = 'ACCEPTED'
       ) AS followingCount

SELECT COUNT(*)
FROM TB_COMM_POST P
WHERE P.POST_SEQ = #{postSeq}
  AND P.POST_STAT = 'ACTIVE'
  AND (
      P.VIS_TYP = 'PUBLIC'
      OR P.USR_ID = #{usrId}
      OR EXISTS (
          SELECT 1
          FROM TB_COMM_FOLLOW F
          WHERE F.FOLLOWER_USR_ID = #{usrId}
            AND F.FOLLOWING_USR_ID = P.USR_ID
            AND F.FOLLOW_STAT = 'ACCEPTED'
      )
  )

SELECT COUNT(*)
FROM TB_COMM_CMT
WHERE POST_SEQ = #{postSeq}
  AND CMT_SEQ = #{cmtSeq}
  AND CMT_STAT = 'ACTIVE'

WITH RANKED_COMMENTS AS ( SELECT C.POST_SEQ AS postSeq , C.CMT_SEQ AS cmtSeq , C.PARENT_CMT_SEQ AS parentCmtSeq , C.USR_ID AS usrId , U.USR_NM AS usrNm , U.PRFL_IMG_FIL_SEQ AS profileImageFilSeq , C.CMT_CN AS cmtCn , TO_CHAR(C.CMT_DTM, 'YYYY-MM-DD"T"HH24:MI:SS') AS cmtDtm , ROW_NUMBER() OVER ( PARTITION BY C.POST_SEQ ORDER BY C.CMT_DTM DESC ) AS rowNum FROM TB_COMM_CMT C JOIN TB_USR U ON U.USR_ID = C.USR_ID JOIN TB_COMM_POST P ON P.POST_SEQ = C.POST_SEQ WHERE C.CMT_STAT = 'ACTIVE' AND P.POST_STAT = 'ACTIVE' AND P.POST_SEQ IN
#{postSeq}
AND C.PARENT_CMT_SEQ IS NULL AND ( P.VIS_TYP = 'PUBLIC' OR P.USR_ID = #{usrId} OR EXISTS ( SELECT 1 FROM TB_COMM_FOLLOW F WHERE F.FOLLOWER_USR_ID = #{usrId} AND F.FOLLOWING_USR_ID = P.USR_ID AND F.FOLLOW_STAT = 'ACCEPTED' ) ) ) SELECT postSeq , cmtSeq , parentCmtSeq , usrId , usrNm , profileImageFilSeq , cmtCn , cmtDtm FROM RANKED_COMMENTS WHERE rowNum <= 2 ORDER BY postSeq, rowNum DESC

mapper.insert:
INSERT INTO TB_COMM_CMT (
    POST_SEQ
    ,  USR_ID
    ,  PARENT_CMT_SEQ
    ,  CMT_CN
    ,  CMT_STAT
    ,  CMT_DTM
    ,  FRST_REG_USER_ID
)
VALUES (
    #{command.postSeq}
    ,  #{command.usrId}
    ,  #{command.parentCmtSeq}
    ,  #{command.commentContent}
    ,  'ACTIVE'
    ,  CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul'
    ,  #{command.frstRegUserId}
)

mapper.update:
UPDATE TB_COMM_CMT
   SET CMT_CN = #{command.commentContent}
    ,  LAST_MOD_USER_ID = #{command.userId}
    ,  LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
WHERE CMT_SEQ = #{command.cmtSeq}
  AND POST_SEQ = #{command.postSeq}
  AND USR_ID = #{command.usrId}
  AND CMT_STAT = 'ACTIVE'

UPDATE TB_COMM_CMT
   SET CMT_STAT = 'DELETED'
    ,  LAST_MOD_USER_ID = #{command.usrId}
    ,  LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
WHERE CMT_SEQ = #{command.cmtSeq}
  AND POST_SEQ = #{command.postSeq}
  AND USR_ID = #{command.usrId}
  AND CMT_STAT = 'ACTIVE'

